/**
 * Git-ignored FLAC investigation inputs (.build/flac-investigation), generated by `npm run bootstrap -- --only
 * flac-investigation` from the vendored generators in tools/bootstrap/flac-investigation against the pinned Native
 * reference. Loading verifies their provenance: the generators and adapter are the lock.json pins, the embedded
 * reference is the local binary and the pin for this platform, and the three files link by hash.
 */
import {createHash} from 'node:crypto';
import {readFileSync} from 'node:fs';
import {pinnedReference,requireGeneratedInput} from './reference-identity.js';

export const FLAC_INVESTIGATION_BOOTSTRAP='npm run bootstrap -- --only flac-investigation';
const directory='.build/flac-investigation';
const hash=(bytes:Uint8Array)=>createHash('sha256').update(bytes).digest('hex');
interface Lock {flacInvestigation:{files:Record<string,string>}}
interface Recorded {reference?:{artifacts?:{ffmpeg?:string;ffprobe?:string}};generatorSha256?:string}
type Name='native-cases.json'|'native-error-cases.json'|'malformed-prototype-result.json';
const generators:Readonly<Record<Exclude<Name,'malformed-prototype-result.json'>,string>>={'native-cases.json':'generate-native-cases.mjs','native-error-cases.json':'generate-error-cases.mjs'};

function lockedFiles():Record<string,string>{return (JSON.parse(readFileSync('tools/bootstrap/lock.json','utf8')) as Lock).flacInvestigation.files;}
function fail(name:string,detail:string):never{throw new Error(`${directory}/${name} ${detail}; regenerate it with ${FLAC_INVESTIGATION_BOOTSTRAP}`);}

/** Bytes and parsed content of one investigation file, after its provenance checks. */
export function flacInvestigationInput<T>(name:Name):{bytes:Buffer;value:T}{
 const bytes=requireGeneratedInput(`${directory}/${name}`,FLAC_INVESTIGATION_BOOTSTRAP),value=JSON.parse(bytes.toString('utf8')) as T&Recorded,files=lockedFiles();
 if(name==='malformed-prototype-result.json'){
  const result=value as T&{adapterSha256?:string;oracleSha256?:string};
  if(result.adapterSha256!==files['prototype/adapter.mjs'])fail(name,`records adapter ${result.adapterSha256}, not the tools/bootstrap/lock.json pin`);
  const oracle=hash(requireGeneratedInput(`${directory}/native-error-cases.json`,FLAC_INVESTIGATION_BOOTSTRAP));
  if(result.oracleSha256!==oracle)fail(name,`records oracle ${result.oracleSha256}, not native-error-cases.json ${oracle}`);
  return {bytes,value};
 }
 const local=hash(readFileSync('.build/reference/ffmpeg')),reference=pinnedReference(),recorded=value.reference?.artifacts?.ffmpeg;
 if(recorded!==local||recorded!==reference.ffmpeg)fail(name,`was generated against ffmpeg ${recorded}, not the local ${local} pinned for ${reference.id}`);
 if(value.generatorSha256!==files[generators[name]])fail(name,`records generator ${value.generatorSha256}, not the tools/bootstrap/lock.json pin of ${generators[name]}`);
 if(name==='native-error-cases.json'){
  const source=hash(requireGeneratedInput(`${directory}/native-cases.json`,FLAC_INVESTIGATION_BOOTSTRAP)),recordedSource=(value as {sourceSha256?:string}).sourceSha256;
  if(recordedSource!==source)fail(name,`records source ${recordedSource}, not native-cases.json ${source}`);
 }
 return {bytes,value};
}
